-- Backup of account_metrics generated by scripts/setup_db.py --sql.
-- Restore: psql "$DATABASE_URL" -f sql/account_metrics.sql
BEGIN;
DROP TABLE IF EXISTS account_metrics;
CREATE TABLE account_metrics (
	account_id INTEGER NOT NULL, 
	income FLOAT, 
	spending FLOAT, 
	household_bills FLOAT, 
	fixed_costs FLOAT, 
	buffer FLOAT, 
	runway_months FLOAT, 
	has_shortfall BOOLEAN, 
	runway_capped BOOLEAN, 
	months_of_history INTEGER, 
	loan_payment FLOAT, 
	card_withdrawals FLOAT, 
	cash_withdrawals FLOAT, 
	transfers_out_other FLOAT, 
	monthly_shortfall FLOAT, 
	goal_target_months INTEGER, 
	goal_target_amount FLOAT, 
	goal_amount_still_needed FLOAT, 
	monthly_surplus FLOAT, 
	goal_progress_pct FLOAT, 
	goal_months_to_goal FLOAT, 
	PRIMARY KEY (account_id)
);
COMMIT;
